3	4fb30963-201d-4455-9ac2-632792b5e259	35	2	full	\N	\N	{"tags": ["zheng_guan_pattern", "wealth_strong"], "scores": {"career_potential": 80, "wealth_potential": 75}, "modules": {"pattern": [{"tags": ["zheng_guan_pattern"], "texts": [], "module": "pattern", "ruleId": "pattern_zheng_guan", "scores": {"career_potential": 80}, "matched": true, "ruleName": "正官格判定"}], "ten_gods": [{"tags": ["wealth_strong"], "texts": [], "module": "ten_gods", "ruleId": "ten_gods_wealth_strong", "scores": {"wealth_potential": 75}, "matched": true, "ruleName": "财星旺盛"}]}, "summary": {"totalMatched": 2, "modulesSummary": [{"module": "pattern", "topTags": ["zheng_guan_pattern"], "matchedCount": 1}, {"module": "ten_gods", "topTags": ["wealth_strong"], "matchedCount": 1}]}}	{"career_potential": 80, "wealth_potential": 75}	["zheng_guan_pattern", "wealth_strong"]	deepseek	2.0.0	{\n  "title": "丁丑年先生全方位命盘深度分析",\n  "overview": "命主日主壬水生于亥月，得令得地，身旺至极。年上丁火正财透出，但被旺水合绊，财星有损；时支寅木食神生财，暗藏生机。格局为正财格，身旺用火土，喜木生火。一生财运起伏，需把握火土旺运；事业上印星护身，官星有制，宜走稳健路线。婚姻中妻星被合，需防感情竞争。健康注意心火与脾胃。总体属于高潜质但需顺运而行的命局。",\n  "sections": [\n    {\n      "title": "命局总论与格局判定",\n      "content": "命主四柱为丁丑、辛亥、壬申、壬寅。日主壬水，生于亥月，水当令而旺，又得月干辛金正印生扶，日支申金为偏印，时干壬水比肩助身，身强无疑。年柱丁丑，丁火为正财，坐丑土财库，但丁壬遥合，财星被日主合绊，有被占有之象，但也表示命主对财富的掌控欲强。时支寅木为食神，暗藏甲木生丙火，为食神生财的源头。综合判断，格局为正财格，身旺以财官为用，喜火土，木亦为喜神（食神生财），忌金水。五行分布：水5、土3、金3、木2、火2，整体偏寒湿，需火调候。丁火暖局为关键，但被壬水所克，用神无力，需大运流年引动方能显效。此命局特点：身旺财弱，比劫夺财明显，需借官杀制比劫或食伤生财来平衡。",\n      "highlights": ["身旺财弱，比劫夺财", "正财合身，掌控欲强", "食神生财，暗藏机遇"],\n      "score": 85,\n      "yearMarks": [\n        {"year": 2026, "label": "财旺暖局，运势爆发", "level": "good"},\n        {"year": 2030, "label": "金旺生水，比劫夺财", "level": "risk"}\n      ]\n    },\n    {\n      "title": "财运深度分析",\n      "content": "正财丁火透于年干，坐丑土财库，但丁壬合，财星被比肩合住，主钱财易被他人分夺，或合作中财务不清。偏财丙火藏于时支寅木之中，长生有情，但未透出，需大运流年引出方可得。丑土为财库，但月支亥水与丑土半会水局，库被水荡，财库不固，容易漏财。时支寅木食神为生财之源，但寅申相冲，木根受损，生财能力受限。求财方向宜火土相关行业，如房地产、能源、餐饮、文化教育等。当前正行丙午大运（30-40岁），干支皆火，为喜用，财运大幅提升，尤其2026丙午年、2027丁未年，火土齐来，为财富爆发年，可积极投资。但2030庚戌年，庚金生水，戌土脆金，金水旺而夺财，需防破财。2031辛亥年，比劫夺财更甚，不宜投机。理财风格宜保守，避免与人合伙，宜独揽财权。",\n      "highlights": ["正财被合，合作宜慎", "食神生财，需防冲克", "丙午大运，财星发力"],\n      "score": 72,\n      "yearMarks": [\n        {"year": 2026, "label": "财运爆发年", "level": "good"},\n        {"year": 2027, "label": "财库逢冲，快进快出", "level": "good"},\n        {"year": 2030, "label": "偏印夺食，投资受损", "level": "risk"},\n        {"year": 2031, "label": "比劫夺财，守财为上", "level": "risk"}\n      ]\n    },\n    {\n      "title": "婚姻感情分析",\n      "content": "男命以正财为妻星，丁火正财在年干，与日主壬水相合，主早年易有恋情，但合而不化，感情不稳定，且比肩争合，有竞争之象。妻星坐丑土，丑为金库，配偶可能从事金融、机械相关职业，性格内敛务实。日支申金为夫妻宫，申为偏印，主配偶思想深邃、有学识，但申金生水，感情中可能缺乏激情，偏于理性。时支寅木为驿马，且寅申冲，婚姻宫逢冲，主婚姻易有变动或两地分居。桃花星少见：月支亥中藏甲，时支寅中藏丙，均非典型桃花，但寅为红鸾星（寅午戌见卯，但寅自带红鸾？实际上红鸾星是：子午卯酉见寅等，此处寅为红鸾的对应？需查，不深究）。最佳结婚年龄段在30岁之后，行火土旺运，财星得力。不利年份：比劫夺财年份如2031辛亥年、2032壬子年，感情易有第三者介入。婚姻稳定性一般，需注意沟通与包容，避免因财务问题争执。",\n      "highlights": ["妻星被合，感情多竞争", "夫妻宫逢冲，易两地分居", "晚婚为宜，30岁后佳"],\n      "score": 65,\n      "yearMarks": [\n        {"year": 2028, "label": "正官透干，贵人牵线", "level": "good"},\n        {"year": 2031, "label": "比劫旺盛，感情危机", "level": "caution"},\n        {"year": 2033, "label": "丑土财库，婚缘成熟", "level": "good"}\n      ]\n    },\n    {\n      "title": "事业职场分析",\n      "content": "命主月干辛金正印，年干丁火正财，时支寅木食神，形成食神生财、财生官之势（丁火生己土，己土暗藏），但官星不透。正印主学业、文职，辛金得月令亥水滋润，学业有成，适合文化教育、科研、金融、管理等领域。年上正财，求财务实，有商业头脑。时支食神，创造力强，但寅申冲，事业多变动。比劫旺，职场竞争激烈，需以印星化解（印化比劫生身），即凭专业能力获得权威。贵人方位：南方（火）、西南（土）。当前丙午大运，正财透干，事业高峰在2026-2027年，财官双美，可晋升掌权。瓶颈期在金水旺的大运，如庚戌运（50-60岁），印旺夺食，需防决策失误。宜往火土方向的城市发展，如南方城市。职场人际中，比劫为竞争者，可借印星（上级、导师）护身。",\n      "highlights": ["印星护身，宜走专业路线", "食神生财，创意可期", "比劫竞争，需借印星"],\n      "score": 80,\n      "yearMarks": [\n        {"year": 2026, "label": "财官双美，事业突破", "level": "good"},\n        {"year": 2028, "label": "正官合身，贵人提携", "level": "good"},\n        {"year": 2030, "label": "印星夺食，谨防瓶颈", "level": "caution"}\n      ]\n    },\n    {\n      "title": "健康养生建议",\n      "content": "命局水旺火弱，金生水，土被水荡，五行偏寒湿。健康隐患在于心火不足（血液循环、心脏）、脾胃湿困（消化系统）以及肾水过旺（需防肾虚寒）。水多泛滥，易有水肿、风湿、女性则妇疾。火主眼睛、心血管，丁火弱需防近视、血压问题。土主肌肉、脾胃，丑土湿土，易腹泻、脾虚。养生方向以温补为主，多食温性食物（牛羊肉、红枣、姜茶），少食生冷。运动宜选择快走、慢跑等生阳运动，多晒太阳。居住环境宜干燥向阳，南方或西南方有利。中医疗法：艾灸关元、足三里，以温阳祛湿。经络方面，多疏通心经、脾经。心态上，水旺者易多思，宜静心养神，避免过度消耗。",\n      "highlights": ["水火失衡，心肾需养", "脾胃湿困，温补为宜", "多晒太阳，居住向阳"],\n      "score": 70,\n      "yearMarks": [\n        {"year": 2027, "label": "火土旺年，体质改善", "level": "good"},\n        {"year": 2030, "label": "金水相生，注意寒湿", "level": "caution"}\n      ]\n    },\n    {\n      "title": "大运流年综合运势",\n      "content": "当前正行丙午大运（约30-40岁），干支皆火，为喜用神，此运十年是人生黄金期，财运、事业均有显著提升。命局得以调候，寒湿化解。未来十年（2024-2033）流年运势如下：2024甲辰年，食神制杀，辰土助财，平稳上升；2025乙巳年，伤官生财，巳火冲申，注意工作变动，但机遇增多；2026丙午年，岁运并临，正财极旺，财运爆发，宜大胆投入；2027丁未年，正财合身，未土冲丑，财库动，投资获利但须防快进快出；2028戊申年，七杀透干，申金复吟，压力大但能借印得权；2029己酉年，正官合身，酉金生水，有贵人但防小人；2030庚戌年，偏印夺食，金旺生水，比劫夺财，风险最高，宜守不宜攻；2031辛亥年，比肩夺财，辛金生水，破财口舌，谨慎；2032壬子年，比劫更旺，财务纠纷，宜静不宜动；2033癸丑年，劫财见库，竞争激烈，但丑土财库得木，有暗财。转折点：2026、2027为上升期，2030、2031为风险期。",\n      "highlights": ["丙午大运十年黄金期", "2026-2027财运巅峰", "2030-2031风险警戒"],\n      "score": 82,\n      "yearMarks": [\n        {"year": 2024, "label": "平稳过渡，宜积累", "level": "good"},\n        {"year": 2025, "label": "变动求财，注意安全", "level": "caution"},\n        {"year": 2026, "label": "大吉，全力进取", "level": "good"},\n        {"year": 2027, "label": "大吉，财库开启", "level": "good"},\n        {"year": 2028, "label": "七杀压力，劳而有成", "level": "good"},\n        {"year": 2029, "label": "贵人相助，稳中求进", "level": "good"},\n        {"year": 2030, "label": "风险最高，守财", "level": "risk"},\n        {"year": 2031, "label": "比劫夺财，慎防破耗", "level": "risk"},\n        {"year": 2032, "label": "低调蛰伏", "level": "caution"},\n        {"year": 2033, "label": "暗财入库，小有收获", "level": "good"}\n      ]\n    }\n  ],\n  "summary": "命主身旺财弱，幸得丙午大运火旺暖局，未来十年先扬后抑。2026-2027为人生高点，宜把握财运与事业；2030-2031需防守，避免破财。婚姻宜晚，健康注意心脾。总体属中上命局，顺运则成。",\n  "keyYears": [\n    {"year": 2026, "event": "财运爆发，事业突破", "importance": "high"},\n    {"year": 2027, "event": "财库冲开，投资获利", "importance": "high"},\n    {"year": 2028, "event": "七杀压力，权责加重", "importance": "medium"},\n    {"year": 2029, "event": "官星合身，贵人提携", "importance": "medium"},\n    {"year": 20