1	0d0dee42-f0ba-431a-9a6e-0588ad12ca01	34	1	free	\N	\N	{"tags": [], "scores": {}, "modules": {}, "summary": {"totalMatched": 0, "modulesSummary": []}}	{}	[]	deepseek	2.0.0	{\n  "title": "命理速断：丁火逢印，伤官佩印之局",\n  "overview": "日主丁火生于辰月，土旺晦火，幸得双甲木正印透干，巳火为根，构成伤官佩印格局。身偏弱，喜木火生扶，忌金水土克耗。",\n  "sections": [\n    {\n      "title": "格局概览",\n      "content": "命局以甲木正印为用，双透天干，印星有力，主智慧、学识与贵人缘。日坐巳火劫财，得兄弟朋友之助。但辰土伤官当令，泄身生财，心思细腻，追求完美，易有精神压力。整体格局为伤官佩印，才华与贵气并存，但需注意土重木折，火弱难化。大运喜走木火之地，可成就不凡。",\n      "highlights": ["双甲正印透干，智慧超群", "日坐劫财，得朋友助力", "伤官当令，心思细腻"],\n      "score": 75,\n      "yearMarks": [\n        {"year": 2026, "label": "丙午年，火旺助身，运势上扬", "level": "good"},\n        {"year": 2027, "label": "丁未年，未土冲丑，注意变动", "level": "caution"}\n      ]\n    },\n    {\n      "title": "近期运势",\n      "content": "当前大运约在庚子运（26-35岁），金水忌神，压力较大。但2026丙午流年，干支皆为火，大补日主，事业财运皆有明显提升，贵人相助，机遇显现。2027丁未，午未合火延续好运，但未土冲丑（大运地支），需防工作环境变动或感情波动。把握火旺之年，积极进取，可奠定未来基础。",\n      "highlights": ["丙午年火旺助身，好运当道", "丁未年注意变动，稳中求进", "贵人运强，善加把握"],\n      "score": 80,\n      "yearMarks": [\n        {"year": 2026, "label": "丙午年，运势高峰", "level": "good"},\n        {"year": 2027, "label": "丁未年，防冲变动", "level": "caution"}\n      ]\n    }\n  ],\n  "summary": "命局伤官佩印，才学不凡，但身弱需助。近两年火旺运起，宜积极发展，尤其2026年丙午，是人生关键转折点。",\n  "keyYears": [\n    {"year": 2026, "event": "丙午年，火旺助身，事业突破", "importance": "high"},\n    {"year": 2027, "event": "丁未年，未土冲运，注意变动", "importance": "medium"}\n  ],\n  "tags": ["伤官佩印", "身弱", "喜木火", "正印"],\n  "overallScore": 75,\n  "upsellHint": "您的命局中暗藏“印星双透”与“伤官生财”的复杂组合，虽有贵人运，但土重木折的隐患需彻底化解。详细报告将揭示未来十年大运的精确走向与关键决策节点，助您趋吉避凶。"\n}	命局伤官佩印，才学不凡，但身弱需助。近两年火旺运起，宜积极发展，尤其2026年丙午，是人生关键转折点。	1579	\N	您的命局中暗藏“印星双透”与“伤官生财”的复杂组合，虽有贵人运，但土重木折的隐患需彻底化解。详细报告将揭示未来十年大运的精确走向与关键决策节点，助您趋吉避凶。	\N	\N	\N	\N	41	2	t	0	2026-04-28 11:47:37.509	\N	\N	\N	\N
5	c5f18237-cec8-4551-a33a-e272bbe9b2d7	34	1	wealth	\N	\N	{"tags": [], "scores": {}, "modules": {}, "summary": {"totalMatched": 0, "modulesSummary": []}}	{}	[]	deepseek	2.0.0	{\n  "title": "财运深度分析报告",\n  "overview": "此命丁火日主，生于辰月，印星甲木双透，然身弱财为忌，正财申金被合化，伤官多而不生财。命局印旺身弱，需木火助身方能任财，财运起伏较大，中年后大运入忌，宜保守求财，专注提升专业技能。",\n  "sections": [\n    {\n      "title": "财星配置分析",\n      "content": "命局中正财申金藏于年支，偏财不显。申金被月时支辰土合化为水（申辰半合水），致正财力量削弱，且年干壬水泄财，财星整体弱而受制。伤官辰土虽多，但土生金之力因辰木盖头而受阻，难以有效生财。印星甲木旺盛，克制伤官，更削弱财源。此命财星不旺且为忌神，需大运流年补足火木助身，方能勉强承担财星。若逢金水旺运，则易因财致祸。",\n      "highlights": ["正财合化，偏财不显", "伤官生财受阻", "印旺克伤官"],\n      "score": 35,\n      "yearMarks": []\n    },\n    {\n      "title": "日主强弱与用神取用",\n      "content": "日主丁火坐巳火自旺，但生于辰月土旺晦火，且天干甲木印星泄火生身，实则木多火塞。综合评定日主偏弱（36.6分）。身弱财为忌，取用神首要助身，以木火为用神，木可生火，火可助势。忌神为土金水，土多晦火，金生水克火，水克火更甚。求财需待身强时，即逢木火流年或大运，方可求财。若强行在忌神运中求财，易破财损身。",\n      "highlights": ["身弱财为忌", "用神木火", "忌神土金水"],\n      "score": 40,\n      "yearMarks": []\n    },\n    {\n      "title": "求财方向与适合行业",\n      "content": "根据五行喜忌，求财宜选择木、火属性行业。木：教育、文化、出版、林业、纺织、医药等；火：能源、餐饮、照明、娱乐、新媒体等。避免土、金、水行业，如房地产、建筑、矿石、金融、物流、渔业等。因印星为用，可通过学历、证书或专业技能提升价值，以知识求财。伤官为忌，不宜投机或过度创新，宜稳守主业。合作求财宜选木火旺的伙伴，避免与土金水旺者合伙。",\n      "highlights": ["宜木火行业", "避免土金水", "以印星求财"],\n      "score": 50,\n      "yearMarks": []\n    },\n    {\n      "title": "十年财运走势（2025-2034）",\n      "content": "当前进入戊申大运（2024-2033），伤官生财但身弱，整体财运压力大。2025乙巳、2026丙午、2027丁未为木火流年，助身有力，可把握机会求财，尤其乙巳年印星透干，利于学业或副业增收。2028戊申、2029己酉、2030庚戌为土金旺年，财星忌神当道，易破财或投资失利，需保守理财。2031辛亥、2032壬子、2033癸丑为水旺官杀年，压力大，谨防因财惹祸。2034甲寅转入己酉大运，甲木印星透出，己土食神，寅木生火，运势转好，可期财运改善。",\n      "highlights": ["2025-2027助身求财", "2028-2033谨慎防破", "2034转运"],\n      "score": 45,\n      "yearMarks": [\n        {"year": 2025, "label": "印助身强，财运小吉", "level": "good"},\n        {"year": 2026, "label": "火旺助身，投资良机", "level": "good"},\n        {"year": 2027, "label": "比劫旺，竞争得财", "level": "good"},\n        {"year": 2028, "label": "财旺克身，风险高", "level": "risk"},\n        {"year": 2029, "label": "财杀相生，谨防破耗", "level": "risk"},\n        {"year": 2030, "label": "官杀混杂，压力巨增", "level": "risk"},\n        {"year": 2031, "label": "水旺火灭，低谷期", "level": "risk"},\n        {"year": 2032, "label": "官杀攻身，守成为上", "level": "risk"},\n        {"year": 2033, "label": "开库但杀旺，慎行", "level": "caution"},\n        {"year": 2034, "label": "印星发力，财运回暖", "level": "good"}\n      ]\n    },\n    {\n      "title": "理财与投资建议",\n      "content": "鉴于身弱财为忌，理财风格宜极度保守。主要收入应来源于稳定工作或专业技能，避免高风险投资如股票、期货、创业等。可配置固定收益类产品、储蓄型保险或不动产（需选择木火区域）。投资时机需选择木火旺的年份（如2025-2027），但也要控制比例，最多不超过可投资资产的30%。忌在土金水年份（2028-2033）扩大投资，且需预留应急资金。比劫夺财风险存在，但自身比劫弱，主要警惕他人借钱或合作纠纷，不轻易担保。",\n      "highlights": ["极度保守", "稳定工作为主", "木火年适度投资"],\n      "score": 30,\n      "yearMarks": []\n    }\n  ],\n  "summary": "身弱财忌，好运需助身。未来十年先吉后凶，2025-2027可求财，2028-2033守成为主，2034后转运。宜木火行业，保守理财。",\n  "keyYears": [\n    {"year": 2026, "event": "火旺助身，投资良机", "importance": "high"},\n    {"year": 2028, "event": "财旺克身，风险高", "importance": "high"},\n    {"year": 2033, "event": "开库但杀旺，慎行", "importance": "medium"},\n    {"year": 2034, "event": "印星发力，财运回暖", "importance": "high"}\n  ],\n  "tags": ["身弱财为忌", "印旺身弱", "伤官合财", "保守理财"],\n  "overallScore": 40,\n  "upsellHint": "如需更精准的流月财运及开运建议，请咨询专业命理师。"\n}	身弱财忌，好运需助身。未来十年先吉后凶，2025-2027可求财，2028-2033守成为主，2034后转运。宜木火行业，保守理财。	3761	\N	如需更精准的流月财运及开运建议，请咨询专业命理师。	\N	\N	\N	\N	4	0	t	0	2026-04-28 18:45:25.607	\N	\N	\N	\N
