20	7c1fde2a-a539-4dd1-bfe3-4c973cae5a32	34	6	wealth	\N	\N	{"tags": [], "scores": {}, "modules": {}, "summary": {"totalMatched": 0, "modulesSummary": []}}	{}	[]	deepseek	2.0.0	{\n  "title": "丁火命盘财运深度分析",\n  "overview": "日主丁火生于辰月，伤官当令，身弱喜木火。原局财星不显，仅年支申中藏庚金正财，弱而受克，求财宜以名带利，不宜直接逐利。伤官配印格，文贵胜于财富，中年后大运助身方有财机。",\n  "sections": [\n    {\n      "title": "财星配置与倾向分析",\n      "content": "原局正财星庚金藏于年支申中，偏财辛金暗藏于辰土墓库（辰为湿土，可藏金但非财库），财星力量极弱且不透干。正财代表稳定收入，偏财代表意外之财，此格局偏财几乎不显，正财亦深藏，故求财需靠专业技能或名声转化。伤官旺而透甲木正印，构成“伤官配印”，主智慧、才艺与贵气，适合从事文化、教育、咨询、设计等靠脑力与名声变现的行业，而非直接经商或投机。身弱财为忌，不宜冒险求财，宜稳中求进。",\n      "highlights": [\n        "正财深藏，偏财不显",\n        "伤官配印，以名带利",\n        "身弱忌财，不宜冒险"\n      ],\n      "score": 55,\n      "yearMarks": [\n        {"year": 2025, "label": "流年印比，稳中有升", "level": "good"},\n        {"year": 2026, "label": "丙火劫财，谨慎合作", "level": "caution"},\n        {"year": 2027, "label": "丁未大运，财星渐现", "level": "good"}\n      ]\n    },\n    {\n      "title": "正财与偏财的倾向分析",\n      "content": "命局正财庚金在年支，代表早年家庭经济条件一般，或父亲事业平淡。正财被年干壬水泄气（壬水为正官，泄财生官），易因工作、名誉而耗财。偏财辛金暗藏于辰土，辰为伤官之库，偏财入墓，主投机运气不佳，不宜炒股、博彩等高风险投资。伤官配印更利于以专业技能赚取稳定报酬，如授课、写作、设计等，属于“知识变现”。中年后运走戊申、己酉，金旺财生，届时可考虑资产配置，但需注意身弱不胜财，要依托团队或合作伙伴。",\n      "highlights": [\n        "正财被官泄，名利转化",\n        "偏财入墓，避免投机",\n        "知识变现为主，后期资产配置"\n      ],\n      "score": 60,\n      "yearMarks": [\n        {"year": 2029, "label": "戊申大运，财星透出", "level": "good"},\n        {"year": 2035, "label": "乙卯流年，印星生身", "level": "good"}\n      ]\n    },\n    {\n      "title": "求财方向与行业选择",\n      "content": "日主丁火，伤官配印，五行喜木火，忌金水。求财方向宜往东方、南方，或多与木火属性行业相关。具体行业：文化教育（木）、设计创意（火）、互联网（火）、咨询策划（火）、林业（木）等。避免金融（金）、物流（水）、冷饮（水）等金水行业。原局辰土湿土，也可考虑房地产（土）但需结合大运，因土生金为忌，故不宜重资产。宜轻资产、重智慧。流年遇木火则财机显现，如水年则需保守。",\n      "highlights": [\n        "东方、南方为吉利方位",\n        "适合文化、教育、互联网",\n        "避免金融、物流等金水行业"\n      ],\n      "score": 70,\n      "yearMarks": [\n        {"year": 2027, "label": "丁未年，食神生财", "level": "good"},\n        {"year": 2031, "label": "辛亥年，官星合身", "level": "caution"}\n      ]\n    },\n    {\n      "title": "未来十年财运走势（2025-2034）",\n      "content": "当前正处丁未大运（约2020-2029），丁火比肩助身，未土食神生财。2025乙巳年，印比两旺，身强可任财，财运平稳上升，适合积累声誉。2026丙午年，劫财旺，注意合作纠纷，不宜投资。2027丁未年，食神生财，收入渠道增多，但未冲辰，变动中求财。2028戊申年，伤官生财，申金正财透出，但身弱，需防劳累过度。2029进入戊申大运，申金正财当运，但戊土伤官生财，身更弱，需寻求合作或借力。2030庚戌年，正财透干，戌为火库助身，财运佳。2031辛亥年，官星合身，压力大，财运平平。2032壬子年，水旺克身，破财风险，宜保守。2033癸丑年，七杀坐财库，丑为金库，但身弱，谨防投资陷阱。2034甲寅年，印旺身强，财运回升。",\n      "highlights": [\n        "2029戊申大运财旺但身弱",\n        "2032壬子年风险极高",\n        "2034甲寅年转机"\n      ],\n      "score": 65,\n      "yearMarks": [\n        {"year": 2025, "label": "稳健发展", "level": "good"},\n        {"year": 2028, "label": "劳累生财", "level": "caution"},\n        {"year": 2032, "label": "水旺破财", "level": "risk"}\n      ]\n    },\n    {\n      "title": "理财与投资建议",\n      "content": "身弱财弱格局，应坚持保守型理财，以储蓄、固收类产品为主，避免高风险股票、期货。原局伤官配印，宜投资自身能力提升（如进修、考证），通过增加名望来间接获利。中年后大运遇金，可适当配置不动产（土生金，但要注意五行平衡），但需选择木火旺的地段或时机。比劫夺财风险主要出现在丙午、丁未年（2026-2027），避免与人合伙或担保。财库开合：原局辰为伤官库，暗藏偏财，逢戌冲辰时（如2030年庚戌，戌冲辰）可能开库，但身弱为忌，宜求稳。",\n      "highlights": [\n        "保守型理财，储蓄为主",\n        "投资自身能力提升",\n        "避免高风险与合伙"\n      ],\n      "score": 50,\n      "yearMarks": [\n        {"year": 2030, "label": "财库开，谨慎把握", "level": "caution"},\n        {"year": 2026, "label": "劫财年，防破财", "level": "risk"}\n      ]\n    }\n  ],\n  "summary": "命主身弱，财星不显，求财应以名带利，专注专业技能提升。中年后大运助身，财星渐现，但需注意身弱不胜财，宜稳中求进。",\n  "keyYears": [\n    {"year": 2025, "event": "印比助身，财运平稳上升", "importance": "medium"},\n    {"year": 2032, "event": "水旺破财，需保守理财", "importance": "high"},\n    {"year": 2034, "event": "印旺身强，财运回升", "importance": "medium"}\n  ],\n  "tags": ["伤官配印", "身弱喜木火", "财星弱", "保守理财"],\n  "overallScore": 60,\n  "upsellHint": "如需更精准的流年财富机遇与风险规避方案，可提供详细出生时辰进行个性化排盘与指导。"\n}	命主身弱，财星不显，求财应以名带利，专注专业技能提升。中年后大运助身，财星渐现，但需注意身弱不胜财，宜稳中求进。	3328	0.0000	如需更精准的流年财富机遇与风险规避方案，可提供详细出生时辰进行个性化排盘与指导。	\N	\N	\N	\N	22	0	t	0	2026-05-01 11:07:40.534	\N	\N	\N	\N
22	c7ff0dfe-8112-4ef7-9441-d72112cf58e4	39	20	wealth	\N	\N	{"tags": [], "scores": {}, "modules": {}, "summary": {"totalMatched": 0, "modulesSummary": []}}	{}	[]	deepseek	2.0.0	{\n  "title": "癸水身弱财旺，求财需借金水之力",\n  "overview": "命主癸水生于巳月，火旺土燥，财星透干，但身弱不胜财。全局金水为喜用，求财宜借印比之力，适合技术、金融、物流等五行金水行业。当前甲寅大运伤官生财，但火势更旺，财运波动较大，需防投资失误。",\n  "sections": [\n    {\n      "title": "财星配置分析",\n      "content": "命局月干丁火为偏财，时支午火藏丁火偏财，月支巳火藏丙火正财，财星透藏兼备，且财星当令而旺。但日主癸水无根，仅年支酉金印星生扶，时干戊土正官合身，形成财官印相生但身弱难担。正财主稳定收入，偏财主意外之财，由于身弱，偏财易带来投机风险，正财更需踏实积累。财星分布在月柱、时柱，中年后财运逐渐显现，但需大运流年引动。",\n      "highlights": [\n        "月干丁火偏财透出，求财主动但易耗神",\n        "时支午火偏财，晚年仍有财运机会",\n        "财星旺而身弱，需金水帮扶方能任财"\n      ],\n      "score": 65,\n      "yearMarks": [\n        {"year": 2025, "label": "伤官生财，机遇与风险并存", "level": "caution"},\n        {"year": 2028, "label": "印星助身，财运回升", "level": "good"},\n        {"year": 2031, "label": "比劫夺财，谨防破耗", "level": "risk"}\n      ]\n    },\n    {\n      "title": "正财偏财倾向",\n      "content": "命局丁火偏财透干，巳火正财藏支，偏财倾向略强。偏财代表大财、投资、经商，正财代表工资、稳定收入。身弱之人不宜过度追求偏财，容易因贪心导致损失。建议以正财为主，稳定工作或技能求财，兼以小额投资。当前甲寅大运，伤官生偏财，创意或技术性收入增加，但火旺耗身，需注意劳逸结合。",\n      "highlights": [\n        "偏财透干，有经商或投资倾向",\n        "身弱难抗偏财波动，应侧重正财积累",\n        "未来大运水旺时可适当扩大投资"\n      ],\n      "score": 60,\n      "yearMarks": []\n    },\n    {\n      "title": "求财方向与行业",\n      "content": "日主癸水，喜金水，忌火土。求财方向宜北、西北，行业五行属金、水，如金融、证券、物流、航运、IT、数据、法律、咨询等。火土行业如餐饮、地产、能源等压力大，不宜深耕。当前甲寅大运，木生火，亦可从事与文化、教育、设计相关（木火）但需搭配金水元素。八字无木，食伤弱，创意产业需借力合作。",\n      "highlights": [\n        "金融、物流、数据等金水行业最佳",\n        "避免地产、能源等火土行业",\n        "偶可涉足文化教育，但需结合自身技能"\n      ],\n      "score": 70,\n      "yearMarks": []\n    },\n    {\n      "title": "十年财运走势（2024-2034）",\n      "content": "当前在甲寅大运（2022-2032），伤官生财，但火炎土燥，身弱难胜。2024甲辰年，甲木伤官生财，辰土水库调候，财运平稳，有小财进账。2025乙巳年，乙木食神透干，巳火财星加重，冲动酉金印星，防投资冲动破财，不宜投机。2026丙午年，财旺耗身，开销大，注意健康。2027丁未年，七杀制身，工作压力大，财运平平。2028戊申年，申金正印生身，申子辰合水局，财运显著提升，可入手稳健理财。2029己酉年，酉金偏印帮身，财官有制，收入稳定增长。2030庚戌年，庚金正印透干，戌土财库被冲，有意外之财但易反复。2031辛亥年，辛金偏印，亥水比劫，比劫夺财，谨防合作破财。2032壬子年，水旺帮身，财运佳，可大胆投资。2033癸丑年，七杀旺，需保守。2034甲寅年，伤官生财，但身弱，宜见好就收。",\n      "highlights": [\n        "2028、2032年为财运爆发年",\n        "2025、2031年为风险年，易破财",\n        "整体走势前低后高，中年后渐入佳境"\n      ],\n      "score": 68,\n      "yearMarks": [\n        {"year": 2024, "label": "平稳过度，小财可期", "level": "good"},\n        {"year": 2025, "label": "冲动投资易损，宜守", "level": "caution"},\n        {"year": 2026, "label": "开销大，财运平淡", "level": "caution"},\n        {"year": 2027, "label": "工作压力，收入持平", "level": "caution"},\n        {"year": 2028, "label": "印星发力，财源广进", "level": "good"},\n        {"year": 2029, "label": "稳中有升，积累为主", "level": "good"},\n        {"year": 2030, "label": "财库逢冲，波动中获利", "level": "caution"},\n        {"year": 2031, "label": "比劫夺财，谨防合伙", "level": "risk"},\n        {"year": 2032, "label": "水旺帮身，财运亨通", "level": "good"},\n        {"year": 2033, "label": "七杀压力，宜保守", "level": "caution"}\n      ]\n    },\n    {\n      "title": "理财与投资建议",\n      "content": "身弱财旺，理财宜保守为主，切勿冒险杠杆。建议将60%资金配置于低风险产品（国债、银行理财），30%用于稳健增值（保险、黄金），10%可尝试小额投资但需见好就收。当前甲寅大运，伤官生财，投资可关注科技、教育类基金，但需逢水旺年份加仓。2032年水旺，可适当加大权益类资产。避免盲目跟风，尤其2025、2031年应暂停投资。建立应急储备金，以应对突发开销。",\n      "highlights": [\n        "保守型理财为主，进取为辅",\n        "关注金水行业投资机会",\n        "水旺年份可适度进取，火土年份守成"\n      ],\n      "score": 72,\n      "yearMarks": []\n    }\n  ],\n  "summary": "癸水身弱财旺，中年后大运得助，财运逐步提升。求财宜借金水之力，专注专业领域，避免投机。未来十年需把握2028、2032年机遇，警惕2025、2031年破财。",\n  "keyYears": [\n    {"year": 2028, "event": "印星生身，财运爆发", "importance": "high"},\n    {"year": 2032, "event": "水旺帮身，投资良机", "importance": "high"},\n    {"year": 2025, "event": "伤官生财，冲动破耗", "importance": "medium"},\n    {"year": 2031, "event": "比劫夺财，谨防合伙损失", "importance": "medium"}\n  ],\n  "tags": ["身弱财旺", "正财格", "喜金水", "中晚年财丰"],\n  "overallScore": 65,\n  "upsellHint": "如需更精准的流月财运指导或财富增长策略，可预约一对一命理咨询，结合姓名、风水等综合调理。"\n}	癸水身弱财旺，中年后大运得助，财运逐步提升。求财宜借金水之力，专注专业领域，避免投机。未来十年需把握2028、2032年机遇，警惕2025、2031年破财。	3174	0.0000	如需更精准的流月财运指导或财富增长策略，可预约一对一命理咨询，结合姓名、风水等综合调理。	\N	\N	\N	\N	12	0	t	1	2026-05-01 12:06:46.861	\N	\N	\N	\N
23	e0cafc2f-a308-4331-9ab1-9147c7565e06	39	21	annual	\N	\N	{"tags": [], "scores": {}, "modules": {}, "summary": {"totalMatched": 0, "modulesSummary": []}}	{}	[]	deepseek	2.0.0	{\n  "title": "2026-2035年流年大运详解",\n  "overview": "命主自2026年进入庚辰大运，庚金偏印为用神，辰土七杀为水库，与原局子辰半合水局，增强日主壬水力量。此大运用神得力，事业财运有望稳步提升，但火土忌神仍存，需防流年引发冲克。整体基调先抑后扬，逐步向好。",\n  "sections": [\n    {\n      "title": "当前大运总论（庚辰 2026-2036）",\n      "content": "命主当前32岁，正行庚辰大运（2026-2036年）。此运庚金偏印生身，辰土七杀助水，原局子辰半合水局，日主壬水由弱转强。用神得力，利于学业、事业、贵人运，尤其适合从事文化、教育、技术等五行属金的行业。但辰土亦藏戊土七杀，与原局年支戌土相冲，需注意长辈健康或房产变动。整体而言，此大运是命主发展的黄金十年，应把握机遇，积极进取。",\n      "highlights": ["用神金水到位", "子辰合水增强日主", "辰戌冲注意家庭变动"],\n      "score": 75,\n      "yearMarks": []\n    },\n    {\n      "title": "2026年丙午运势",\n      "content": "2026年为丙午年，丙火偏财透干，午火正财坐实，火势极旺。原局双丙午火，财星过旺克身，虽有大运庚金化火生水，但火炎金熔，喜忧参半。财运方面，求财机会多，但耗身严重，易因财致累，不宜冒险投资。事业上压力大，需注意劳逸结合。感情上男命财星为妻，火旺易有缘分，但关系紧张。健康方面，注意心脏、血压问题。关键月份：五月午火最旺，十二月子午冲，均需谨慎。",\n      "highlights": ["财星极旺耗身", "事业压力大", "注意健康"],\n      "score": 45,\n      "yearMarks": [\n        {"year": 2026, "label": "火旺财多身弱", "level": "risk"}\n      ]\n    },\n    {\n      "title": "2027年丁未运势",\n      "content": "2027年为丁未年，丁火正财，未土正官，火土忌神齐来。丁壬合，合去日主，有被情事牵绊之象。未土与命局子未相害，辰未相破，人际关系复杂，易有口舌是非。财运平平，不宜投机。事业上官星为忌，压力增大，但未土为燥土，晦火生金，尚存一丝生机。感情上已婚者易有矛盾，单身者谨慎开始。健康注意脾胃、皮肤。关键月份：六月未月土旺，腊月丑月冲未，注意变化。",\n      "highlights": ["火土忌神加重", "人际是非多", "感情需谨慎"],\n      "score": 40,\n      "yearMarks": [\n        {"year": 2027, "label": "火土忌神年", "level": "risk"}\n      ]\n    },\n    {\n      "title": "2028年戊申运势",\n      "content": "2028年为戊申年，戊土七杀透干，申金偏印坐支。申金为用神，与命局子辰三合水局，日主极强。戊土七杀虽克身，但有申金化杀生身，为杀印相生之贵格。事业上压力化为动力，得到贵人相助，职位提升有望。财运因印星生身而佳，但七杀制身，需付出努力。感情运势平稳，男命七杀为子女星，利于生育。健康良好。关键月份：七月申月金旺，十月亥月水旺，吉。",\n      "highlights": ["杀印相生，事业上升", "贵人运强", "三合水局助力"],\n      "score": 80,\n      "yearMarks": [\n        {"year": 2028, "label": "贵人年", "level": "good"}\n      ]\n    },\n    {\n      "title": "2029年己酉运势",\n      "content": "2029年为己酉年，己土正官，酉金正印。酉金为用神，与命局辰酉合化金，印星力量大增。己土官星被金泄气，官变为闲神。运势顺遂，利于考试、进修、签约。事业上易得领导赏识，权责增加。财运平稳，正财收入提升。感情上男命正官合日主，与伴侣关系融洽。健康注意肺经、呼吸道。关键月份：八月酉月金旺，吉。",\n      "highlights": ["印星合化得力", "官星有情", "事业顺利"],\n      "score": 83,\n      "yearMarks": [\n        {"year": 2029, "label": "事业丰收年", "level": "good"}\n      ]\n    },\n    {\n      "title": "2030年庚戌运势",\n      "content": "2030年为庚戌年，庚金偏印透干，戌土七杀坐支。庚金为用神，但戌土为忌神，且与年支戌土伏吟，与日支辰土相冲，引发原局辰戌冲。此年变动较大，工作、住所易有变化。戌为火库，火势入墓，忌神有所收敛。财运一般，不宜投资。事业上竞争激烈，需防小人。感情上因冲克，易有争吵。健康注意肠胃、肾水。关键月份：三月辰月冲戌，九月戌月伏吟，注意。",\n      "highlights": ["辰戌相冲，变动多", "竞争激烈", "需防小人"],\n      "score": 55,\n      "yearMarks": [\n        {"year": 2030, "label": "冲克变动年", "level": "caution"}\n      ]\n    },\n    {\n      "title": "2031年辛亥运势",\n      "content": "2031年为辛亥年，辛金正印透干，亥水比肩坐支。亥水为喜神，与命局寅亥合木，但木为食伤，可泄身生财。辛金印星生身，总体吉顺。事业上得到同事朋友帮助，团队协作顺利。财运因食伤而生，投资有机会。感情上男命亥水为比肩，注意竞争者。健康良好。关键月份：十月亥月水旺，吉。",\n      "highlights": ["印比相助", "团队合作顺利", "财源有路"],\n      "score": 78,\n      "yearMarks": [\n        {"year": 2031, "label": "比助印生年", "level": "good"}\n      ]\n    },\n    {\n      "title": "2032年壬子运势",\n      "content": "2032年为壬子年，壬水比肩透干，子水阳刃坐支。子水为羊刃，与命局子水并见，加强自身力量。但阳刃见刃，易有争斗、破财之象。比肩旺，利于合作，但需防朋友失信。财运上羊刃夺财，不宜合伙投资。事业上竞争激烈，但自身实力增强。感情上男命子水为阳刃，易有桃花但不稳定。健康注意泌尿系统。关键月份：十一月子月阳刃旺，注意。",\n      "highlights": ["阳刃见刃，争斗多", "比肩旺防破财", "合作需谨慎"],\n      "score": 60,\n      "yearMarks": [\n        {"year": 2032, "label": "阳刃年", "level": "caution"}\n      ]\n    },\n    {\n      "title": "2033年癸丑运势",\n      "content": "2033年为癸丑年，癸水劫财透干，丑土正官坐支。丑土与命局子丑合，子水被合绊，日主力量减弱。癸水劫财，有竞争、损耗之象。官星合身，事业上压力与机遇并存。财运不佳，注意破财。感情上丑土为正官，男命女缘平淡。健康注意肠胃。关键月份：十二月丑月土旺，注意。",\n      "highlights": ["劫财官星组合", "竞争压力大", "财运谨慎"],\n      "score": 50,\n      "yearMarks": [\n        {"year": 2033, "label": "劫财官星年", "level": "caution"}\n      ]\n    },\n    {\n      "title": "2034年甲寅运势",\n      "content": "2034年为甲寅年，甲木食神透干，寅木食神坐支。食神旺，可泄身生财，但原局木为忌神，且寅木与命局午戌三合火局，引发火势。财星得食神生，求财欲望强，但火旺克身，易因求财劳累。事业上创意多，但执行易受阻。感情上食神生财，桃花运旺，但需防多情。健康注意肝胆、心脏。关键月份：正月寅月、五月午月、九月戌月合火，注意。",\n      "highlights": ["食神生财，求财心切", "三合火局，财旺身弱", "桃花运旺"],\n      "score": 52,\n      "yearMarks": [\n        {"year": 2034, "label": "食神生财年", "level": "caution"}\n      ]\n    },\n    {\n      "title": "2035年乙卯运势",\n      "content": "2035年为乙卯年，乙木伤官透干，卯木伤官坐支。伤官旺，与命局子卯相刑，且与原局年支戌合火。伤官为忌，易有口舌是非，变动多。事业上不宜冲动，谨言慎行。财运一般，伤官生财但需防破耗。感情上伤官克官，男命易与伴侣争执。健康注意肝气郁结。关键月份：二月卯月，子卯刑，注意人际。",\n      "highlights": ["伤官刑合，是非多", "变动不安", "感情易冲突"],\n      "score": 43,\n      "yearMarks": [\n        {"year": 2035, "label": "伤官是非年", "level": "risk"}\n      ]\n    }\n  ],\n  "summary": "未来十年，前三年火旺为忌，谨慎行事；2028年后金水用神得力，运势渐入佳境，尤其是2028-2029、2031年为黄金期；2034-2035年火土木再次抬头，需稳健理财，规避风险。",\n  "keyYears": [\n    {"year": 2028, "event": "杀印相生，贵人提拔", "importance": "high"},\n    {"year": 2029, "event": "印星合化，事业丰收", "importance": "high"},\n    {"year": 2031, "event": "印比相助，团队合作顺利", "importance": "medium"},\n    {"year": 2034, "event": "桃花旺但财多身弱", "importance": "medium"}\n  ],\n  "tags": ["用神大运", "先抑后扬", "金水得力", "火土忌神", "辰戌冲"],\n  "overallScore": 65,\n  "upsellHint": "如需更精细的每月运势及趋吉避凶策略，建议进行流月详批。"\n}	未来十年，前三年火旺为忌，谨慎行事；2028年后金水用神得力，运势渐入佳境，尤其是2028-2029、2031年为黄金期；2034-2035年火土木再次抬头，需稳健理财，规避风险。	4486	0.0000	如需更精细的每月运势及趋吉避凶策略，建议进行流月详批。	\N	\N	\N	\N	6	0	t	1	2026-05-01 12:14:53.74	\N	\N	\N	\N
