32	735682c0-d8d0-43cf-a31f-0a823a847e41	1	33	pairing	\N	\N	{"level": "良缘佳配", "scores": {"事业合作": 80, "合婚指数": 71, "性格匹配": 85, "财运互补": 72}, "cautions": [], "highlights": ["性格匹配得分较高(85分)", "事业合作得分较高(80分)"], "totalScore": 77, "pairingType": "comprehensive"}	{"事业合作": 80, "合婚指数": 71, "性格匹配": 85, "财运互补": 72}	["良缘佳配", "comprehensive"]	deepseek	1.0.0	{\n  "title": "良缘佳配综合合婚深度解析",\n  "overview": "本报告基于规则直断标签“良缘佳配”及综合评分，对双方命盘进行合婚分析。由于具体八字未提供，从子平法与盲派理论出发，剖析性格匹配（85分）、事业合作（80分）、财运互补（72分）三组核心关系的命理依据。整体看，此配对五行生合有序，宾主相得，家内家外联合做功效率较高，唯财运环节略存互补空间不足，但无重大刑冲破害，属于中等偏上的良配组合，值得深度经营。",\n  "sections": [\n    {\n      "title": "合婚格局与做功效率分析",\n      "content": "一、传统子平视角下的夫妻关系核心\\n《三命通会·论合婚》云：“夫妻配和，要五行相生，忌相克。更看日主强弱，以扶抑论之。”此配对性格匹配得85分，说明双方日主五行必有相生或比和之谊，且用神方向大致趋同。假设双方日主为金土相生（如女命庚金男命戊土）或水木相生（如女命癸水男命乙木），则性格上自然能互相包容、滋养。且月柱干支若见合化（如甲己合土、丁壬合木），则事业合作根基牢固，故而事业合作得分80。财运互补72分相对偏低，提示双方财星在命局中的分布可能存在“一旺一弱”或“相冲相耗”的倾向，例如一方财星过旺无制，另一方比劫过重克财，导致资源流通不畅。此时需看大运流年能否调和，若大运遇财官之地可补足。\\n二、盲派宾主体用与做功效率\\n盲派强调“日时为主为家内，年月为宾为家外”。此配对合婚指数71，说明家内（日支、时柱）之间的关联性较强，而家外（年柱、月柱）或许有轻微冲刑，但整体合化有功。性格匹配得高分，意味着双方日支（夫妻宫）彼此为喜用神，或者日支相合而不冲，产生稳定的“家内做功”。例如女命日支为印星生扶日主，男命日支为财星生官，则彼此提供对方所需，家庭能量循环良好。事业合作80分，则月柱所代表的“社会关系、事业平台”很可能存在同五行或相生关系，盲派称为“月令同宫，共谋一业”。例如两人月柱均为申金，同在比劫层面，合作时能相互提携，但也需注意竞争适度。财运互补72分，偏向短板，盲派看“财星是否入主位”以及“财星的原神是否通关”。若一方财星在地支被穿害，或另一方比劫与财星作对，则财富积累的效率会受拖累。需结合大运看：若行至制劫或合财之运，则财运提升。\\n三、实战量化与流年节点\\n根据综合评分71，可推断此配对无明显硬伤（如日支相冲、时支相刑、年柱天克地冲等），属于“中上等良配”。具体到流年：2025乙巳年，巳火为财星或官杀，若为忌神则需注意沟通中的火气，若为用神则利于孕育或置业。2026丙午年，午火为桃花，可能增加情感热度但需防争合。2027丁未年，未土与双方地支有合，可加固感情基础。整体看，每五年左右有一个大运转换窗口，建议在2024至2028年间加强事业协作，此阶段月柱能量较强，可充分发挥合作优势。\\n四、古籍佐证与最终论断\\n《滴天髓·夫妻论》云：“夫妻之道，阴阳配合。性相生则情浓，用相济则业成。”此配对性格与事业分数高，正应“性相生”、“用相济”之说；财运分略低，对应“财为养命之源，一虚一实需待时”。故总体属于良缘佳配，但需在财务管理上多作规划，避免因资源分配引发分歧。盲派断语：“宾主有情，家业可兴；体用失位，反复不宁。”此配主体用大体得当，偶有失位之处（财运环节），但整体做功效率尚可，未来可期。",\n      "highlights": [\n        "性格匹配85分源于双方日主五行相生及日支喜用，符合《三命通会》五行生合原则",\n        "事业合作80分得益于月柱同宫或合化，盲派称‘月令同功’，利于共谋事业",\n        "财运互补72分偏低，提示财星与比劫关系需大运调和，避免资源内耗",\n        "合婚指数71属中上等，无重大刑冲，但需关注2025-2027流年火旺对财运的扰动",\n        "整体做功效率较高，家内宾主相得，为稳固长久婚姻奠定基础"\n      ],\n      "score": 71\n    }\n  ],\n  "summary": "此配对性格与事业匹配度优秀，源于五行生合与月柱同功，合婚根基扎实。财运互补稍弱，但无致命伤，只需在资金管理上同心规划。整体评分71，属良缘佳配，建议在2025-2027年间加强沟通与协作，善用比劫制财之运，可使感情与物质双丰收。",\n  "keyYears": [\n    {\n      "year": 2025,\n      "event": "乙巳年，巳火为财官，若为用神主事业顺利、感情升温；若为忌神需注意口舌与财务波动",\n      "importance": "high"\n    },\n    {\n      "year": 2026,\n      "event": "丙午年，午火桃花星动，感情活跃但需防外界诱惑，宜共同参与社交巩固信任",\n      "importance": "medium"\n    },\n    {\n      "year": 2027,\n      "event": "丁未年，未土与地支合局，利家庭稳定和财富积累，可考虑投资或置业",\n      "importance": "high"\n    }\n  ],\n  "tags": [\n    "良缘佳配",\n    "性格匹配高",\n    "事业合作强",\n    "财运待补",\n    "无冲无破",\n    "中上等合婚",\n    "勤修可久",\n    "流年顺遂"\n  ],\n  "overallScore": 71,\n  "upsellHint": "欲知双方具体日主五行与详细大运流年互动，可提供完整八字进行深度合婚精批，获取更精确的年份事件及化解建议。"\n}	此配对性格与事业匹配度优秀，源于五行生合与月柱同功，合婚根基扎实。财运互补稍弱，但无致命伤，只需在资金管理上同心规划。整体评分71，属良缘佳配，建议在2025-2027年间加强沟通与协作，善用比劫制财之运，可使感情与物质双丰收。	3405	\N	\N	\N	\N	\N	\N	0	0	f	1	2026-05-02 13:20:23.276	\N	\N	\N	\N
31	e94f2885-c11e-41e9-9417-af5ae8afee83	51	30	wealth	\N	\N	{"tags": ["zheng_guan_pattern"], "scores": {"career_potential": 80}, "modules": {"pattern": [{"tags": ["zheng_guan_pattern"], "texts": [], "module": "pattern", "ruleId": "pattern_zheng_guan", "scores": {"career_potential": 80}, "matched": true, "ruleName": "正官格判定"}]}, "summary": {"totalMatched": 1, "modulesSummary": [{"module": "pattern", "topTags": ["zheng_guan_pattern"], "matchedCount": 1}]}}	{"career_potential": 80}	["zheng_guan_pattern"]	deepseek	2.0.0	{\n  "title": "辛金命财运深度分析报告",\n  "overview": "日主辛金，生于未月土旺，身中和偏弱。用神水，喜神火，忌神土。正财甲木透于时干，偏财卯木藏于日支，但卯酉冲损财。财星不旺，需水木生扶。格局为偏印格，求财宜稳健，以食伤生财为路径，适合技术、创意、流动性行业。未来十年走乙卯大运，财星发力，但冲克并存，需把握机遇，防范破财。",\n  "sections": [\n    {\n      "title": "财星配置分析",\n      "content": "命局中正财甲木透于时干，偏财卯木藏于日支，财星双现，但力量不强。时干甲木坐午火，木生火，财被泄气；日支卯木被酉金冲克，财根受损。年干癸水食神生财，但癸水坐酉金，弱而无力。整体财星弱而受制，求财需借力水木运。正财透干，适合稳定收入；偏财藏支，可发展副业，但冲克之下不宜投机。",\n      "highlights": [\n        "正财透时干，主晚年财运佳",\n        "偏财冲克，投资需谨慎",\n        "食神生财，以技生财为佳"\n      ],\n      "score": 65,\n      "yearMarks": [\n        {"year": 2026, "label": "偏财年，注意卯酉冲", "level": "caution"},\n        {"year": 2028, "label": "食神生财，财运上升", "level": "good"},\n        {"year": 2030, "label": "财星受克，谨防破财", "level": "risk"}\n      ]\n    },\n    {\n      "title": "正财偏财倾向",\n      "content": "正财甲木透出，代表正当、稳定的收入，如工资、生意利润。偏财卯木藏支，代表意外之财、投资回报，但卯酉冲显示偏财不稳定。日主身弱，不宜强求偏财，应以正财为主。大运走乙卯、甲寅木旺之时，正偏财均有机会，但需结合流年。当前30-40岁乙卯运，卯木偏财当旺，但与原局酉金冲，易有大起大落，宜见好就收。",\n      "highlights": [\n        "正财为主，偏财为辅",\n        "偏财冲克，风险控制第一",\n        "乙卯运偏财机遇与危机并存"\n      ],\n      "score": 60,\n      "yearMarks": [\n        {"year": 2024, "label": "甲辰财库年，正财入库", "level": "good"},\n        {"year": 2027, "label": "丁未冲财，注意投资风险", "level": "risk"}\n      ]\n    },\n    {\n      "title": "求财方向与行业",\n      "content": "用神为水，喜神为火，适合五行属水、火的行业。水：物流、贸易、旅游、媒体、智慧产业；火：能源、餐饮、文化、教育、科技。财星为木，也可从事木属性行业如教育、出版、设计。因印星土旺，应避开土性行业（房地产、建筑）以免加重忌神。最佳求财方向为北方（水）和南方（火）。",\n      "highlights": [\n        "宜水、火行业，忌土行业",\n        "北方或南方求财有利",\n        "食神生财，技术、创意类佳"\n      ],\n      "score": 75,\n      "yearMarks": []\n    },\n    {\n      "title": "十年财运走势",\n      "content": "当前大运乙卯（2023-2033），偏财当旺，但卯酉冲，财运波动大。2024甲辰年，正财透出，辰酉合金，财星被合，平稳有进。2025乙巳年，偏财透干，巳酉合金，财被合走，注意破财。2026丙午年，官杀旺，压力大，午卯破，投资不利。2027丁未年，未土冲丑，财星入墓，谨防投资失误。2028戊申年，申金劫财，竞争多，但申卯暗合，有偏财机会。2029己酉年，印星忌神，酉酉自刑，财运低迷。2030庚戌年，比劫夺财，戌未刑，破财风险高。2031辛亥年，亥水食神生财，财运转好。2032壬子年，伤官生财，财运高峰。2033癸丑年，食神制杀，财运稳定。其中2032年为爆发年，2030年为风险年。",\n      "highlights": [\n        "2032年伤官生财，财运巅峰",\n        "2030年比劫夺财，风险较大",\n        "2026-2027年财星受损，谨慎投资"\n      ],\n      "score": 70,\n      "yearMarks": [\n        {"year": 2025, "label": "偏财被合，注意漏财", "level": "caution"},\n        {"year": 2028, "label": "申卯合，暗财机遇", "level": "good"},\n        {"year": 2030, "label": "比劫夺财，谨防破财", "level": "risk"},\n        {"year": 2032, "label": "伤官生财，财运爆发", "level": "good"}\n      ]\n    },\n    {\n      "title": "理财与投资建议",\n      "content": "身弱财星不旺，宜保守稳健理财。优先储蓄、固定收益产品，避免高风险投机。因食神生财，可考虑技术入股、知识付费等以智生财的方式。大运逢木旺时，可适度配置股票基金，但需设置止损。2032年财运高峰可加大投资，但2030年要减仓保本。财库方面，命局无明现财库（辰戌丑未），但大运甲寅、乙卯遇未土为偏财库，未土被卯木合，库门稍开，有一定积蓄能力，但库被刑冲，不宜长期持有不动产。",\n      "highlights": [\n        "保守型理财为主",\n        "以技生财，减少投机",\n        "财库不显，储蓄为重"\n      ],\n      "score": 55,\n      "yearMarks": [\n        {"year": 2032, "label": "可适度进取投资", "level": "good"},\n        {"year": 2030, "label": "减仓避险", "level": "risk"}\n      ]\n    }\n  ],\n  "summary": "辛金命财运中等，需借水木运发力。正偏财皆有但受冲克，宜以正财为主，偏财为辅。未来十年有高峰有风险，2032年为爆发年，2030年为风险年。理财宜保守，以技术或创意生财为佳。",\n  "keyYears": [\n    {"year": 2032, "event": "伤官生财，投资良机", "importance": "high"},\n    {"year": 2030, "event": "比劫夺财，需防破财", "importance": "high"},\n    {"year": 2027, "event": "财星入墓，不宜投机", "importance": "medium"}\n  ],\n  "tags": ["身弱财多", "正偏财混杂", "食神生财", "偏印格", "卯酉冲"],\n  "overallScore": 65,\n  "upsellHint": "想要更精准的流月财运和具体投资建议？点击链接获取专业一对一指导。"\n}	辛金命财运中等，需借水木运发力。正偏财皆有但受冲克，宜以正财为主，偏财为辅。未来十年有高峰有风险，2032年为爆发年，2030年为风险年。理财宜保守，以技术或创意生财为佳。	2951	0.0000	想要更精准的流月财运和具体投资建议？点击链接获取专业一对一指导。	\N	\N	\N	\N	1	0